function [Ra DEavg T duv]=CIECRI_c(spd,thetas,scalingpars)
if nargin<2;thetas=[0 360];scalingpars=4.6;end
if nargin<3;scalingpars=4.6;end

%run regular code
[~, Ri, T, duv, DEavg, XYZR_,~,sampleset]=CIECRI(spd,[0 360]);

%--------------------------------------------------------------------------

%correct metric calculation for possible missing samples
[usesamples,Nsamples]=selectsampleswithinhueintervalthetas(thetas,sampleset(:,1:9),2);%select samples within hue interval

%calculate new average index/DE
DEi=(100-Ri)./4.6;
DEavg=mean(DEi(usesamples));

% Apply rescaling
if sum(usesamples)==Nsamples
    %keep regular rescaling parameters
    rescaling_pars=[4.6];%F4 at 51
else
    %use new for particular subset of samples
    rescaling_pars=scalingpars;
end
Ra=100-DEavg.*rescaling_pars;

end

