function [CRI CRIi T dc DEavg XYZR_ XYZT_,sampleset]=CIECRI(spd,thetas,ref)
%  This program is used to calculate colour rendering index based on CIE Recommendation (CIE 13.3)
% S1 represents for the SPD of the test light source, it should be at 5nm interval
% ST is the start point of S1 , with the minimum value of 360
% END is the end point of S1, with the maximum value of 830 
% The program gives the results of CRI (general colour rendering index),CRIi ( special colour rendering index for test samples No.1 to No.14), and T (correlated colour temperature of the test light source)
if nargin<2;thetas=[0,360];end
if nargin < 3;
    [CRI CRIi T dc DEavg XYZR_ XYZT_,sampleset]=CIERa(spd,thetas);
end
if nargin ==3
    [CRI CRIi T dc DEavg XYZR_ XYZT_,sampelset]=CIERa(spd,thetas,ref);
end
    
end

